import type { School } from './school-model';

export const StaffRoleKeyToLabel = {
  'Principal': 'Principal',
  'VicePrincipal': 'Vice Principal',
  'DistrictLeader': 'District Leader',
  'LearningSupportTeacher': 'Learning Support Teacher',
  'DataAnalyst': 'Data Analyst'
} as const;
export type StaffRoleKey = keyof typeof StaffRoleKeyToLabel;

export interface Staff {
  /**
   * @displayName Staff ID
   * @description Unique system identifier - GUID generated by system
   * @uiConstraints NEVER create input fields for this ID
   */
  id: string;
  /**
   * @displayName Staff Name
   * @description Human-readable record identifier
   * @validationRule Required for create/update operations
   */
  staffName: string;
  /**
   * @displayName Email
   * @validationRule Required for create/update operations
   */
  email: string;
  /**
   * @displayName Is Active
   * @validationRule Required for create/update operations
   */
  isActive: boolean;
  /**
   * @displayName Manager
   */
  manager?: Pick<Staff, 'id' | 'staffName'>;
  /**
   * @displayName Phone
   */
  phone?: string;
  /**
   * @displayName Role
   * @validationRule Required for create/update operations
   */
  roleKey: StaffRoleKey;
  /**
   * @displayName School
   * @validationRule Required for create/update operations
   */
  school: Pick<School, 'id' | 'schoolName'>;
}

export const _Staff = 'Staff' as const;